python3 - <<'EOF'
import re
from datetime import datetime

path = "team-meeting.ics"
with open(path, "r", newline="") as f:
    content = f.read()

errors = []

# Containers
for token in ["BEGIN:VCALENDAR", "END:VCALENDAR", "BEGIN:VEVENT", "END:VEVENT",
              "VERSION:2.0", "PRODID:"]:
    if token not in content:
        errors.append(f"Missing {token}")

# CRLF line endings
if not re.fullmatch(r"(?:[^\r\n]*\r\n)+", content):
    errors.append("Not all lines are CRLF-terminated")

# Line length (RFC 5545: <=75 octets per line, no folding needed here)
for i, line in enumerate(content.split("\r\n"), 1):
    if len(line.encode()) > 75:
        errors.append(f"Line {i} exceeds 75 octets (needs folding): {len(line.encode())}")

# VEVENT block checks
m = re.search(r"BEGIN:VEVENT\r\n(.*?)\r\nEND:VEVENT", content, re.S)
block = m.group(1) if m else ""

def has(field):
    return re.search(rf"^{re.escape(field)}(?:;|:)", block, re.M) is not None

for req in ["UID", "DTSTAMP", "DTSTART", "DTEND", "SUMMARY", "STATUS", "SEQUENCE"]:
    if not has(req):
        errors.append(f"VEVENT missing {req}")

if has("DTEND") and has("DURATION"):
    errors.append("VEVENT has both DTEND and DURATION")

dtstamp = re.search(r"DTSTAMP:(\d{8}T\d{6}Z)", block)
if not dtstamp:
    errors.append("DTSTAMP must match YYYYMMDDTHHMMSSZ")

start = re.search(r"DTSTART;TZID=([^:]+):(\d{8}T\d{6})", block)
end = re.search(r"DTEND;TZID=([^:]+):(\d{8}T\d{6})", block)
if start and end:
    if start.group(1) != end.group(1):
        errors.append("DTSTART and DTEND timezones differ")
    fmt = "%Y%m%dT%H%M%S"
    if datetime.strptime(end.group(2), fmt) <= datetime.strptime(start.group(2), fmt):
        errors.append("DTEND must be after DTSTART")
elif not start:
    errors.append("DTSTART must use TZID local format")
elif not end:
    errors.append("DTEND must use TZID local format")

# Known timezone reference check (lightweight)
tzids = set(re.findall(r"TZID=([^:;\r\n]+)", content))
known = {"Asia/Shanghai", "Asia/Tokyo", "UTC", "America/New_York", "America/Chicago",
         "America/Denver", "America/Los_Angeles", "Europe/London", "Europe/Paris"}
for tz in tzids:
    if tz not in known:
        errors.append(f"Unrecognized TZID: {tz}")

# VALARM sanity
if "BEGIN:VALARM" in block:
    if "TRIGGER:-PT15M" not in block or "ACTION:DISPLAY" not in block:
        errors.append("VALARM malformed")
else:
    errors.append("No VALARM reminder present")

print("Validation result:", errors if errors else "Valid")
EOF
